import { Pokemon } from '../enums/pokemon';
import { Abilities } from '../enums/abilities';

/**
 * Pokemon competitive set data imported from Smogon usage statistics
 * Each Pokemon has weighted abilities and EV spreads based on usage
 */

export interface PokemonSpread {
  spread: string; // Format: "Nature:HP/Atk/Def/SpA/SpD/Spe"
  weight: number; // Percentage (0-100)
}

export interface PokemonSetData {
  pokemonId: Pokemon;
  abilities: { [abilityId: number]: number }; // Ability ID -> percentage
  spreads: PokemonSpread[]; // Top 20 spreads, normalized to 100%
}

